              "assumptions": {
                "type": [
                  "array",
                  "null"
                ],
                "items": {
                  "type": "string"
                }
              },
              "rationale": {
                "type": [
                  "string",
                  "null"
                ]
              }
            },
            "required": [
              "text",
              "sourceArtifactItemIds",
              "assumptions",
              "rationale"
            ]
          }
        }
      },
      "required": [
